do $$ declare rid bigint; begin
  perform pg_advisory_xact_lock(280281);
  if exists (select 1 from ten280_bot.events where kind = 'startup_v2') then return; end if;
  rid := ten280_bot.send('✅ Stennisfy — Bet105 drop bot UPDATED (test message).' || chr(10)
      || 'Alerts: Bet105 match winner, ATP / Challenger / ITF Men, pre-match. Fires on a ≥5% drop vs the price 10 min earlier; 30-min cooldown per match.' || chr(10)
      || 'Test phase: drops to prices below 1.30 are included.' || chr(10)
      || '"Moved" = time from the price change to the moment the alert is sent. Times in UTC.' || chr(10) || chr(10)
      || 'Next message: a FORMAT TEST — the most recent live alert re-sent in the new layout (its Moved = the delay when it first fired).');
  insert into ten280_bot.events (kind, detail, net_request_id, delivery) values ('startup_v2', jsonb_build_object('at', now()), rid, case when rid is null then 'unsent: no vault secret' else 'queued' end);
end $$; select id, kind, delivery from ten280_bot.events where kind = 'startup_v2'

do $$ declare rid bigint; a ten280_bot.alerts; msg text; begin
  perform pg_advisory_xact_lock(280281);
  if exists (select 1 from ten280_bot.events where kind = 'format_test') then return; end if;
  perform pg_sleep(2);  -- keep it after the startup message
  select * into a from ten280_bot.alerts where mode = 'live' and delivery = 'sent' order by id desc limit 1;
  if a.id is null then raise exception 'no live alert to re-send'; end if;
  msg := ten280_bot.render(a, coalesce(a.sent_at, a.eval_at));
  rid := ten280_bot.send(msg);
  insert into ten280_bot.events (kind, detail, net_request_id, delivery) values ('format_test', jsonb_build_object('alert_id', a.id, 'text', msg), rid, case when rid is null then 'unsent: no vault secret' else 'queued' end);
end $$; select id, kind, delivery from ten280_bot.events where kind = 'format_test'
